query OrphanScanCollections($cursor: String) {
            collections(first: 50, after: $cursor) {
              pageInfo { hasNextPage endCursor }
              edges {
                node {
                  id
                  title
                  products(first: 250) {
                    pageInfo { hasNextPage }
                    nodes { id }
                  }
                }
              }
            }
          }

query OrphanScanProducts($cursor: String) {
            products(first: 50, after: $cursor) {
              pageInfo { hasNextPage endCursor }
              edges {
                node {
                  id
                  title
                  handle
                  status
                  contentStatus: metafield(namespace: "custom", key: "content_status") { value }
                  summaryPoints: metafield(namespace: "custom", key: "summary_points") { value }
                }
              }
            }
          }
